// Portal compose, app side (spec v0.7 §6/§8): the TS port of Athena's compose_rules.py held to the SHARED fixture byte for byte.
// Run: npx --no-install tsx --test src/lib/compose/compose-rules.test.ts
//
// The fixture (compose-vectors-v1.json) is Athena's, generated by her Python reference + svrnty's own signWithEnvelope with a THROWAWAY key.
// It is copied here UNCHANGED and pinned by sha1, so a silent edit (or a stale copy) fails the first test instead of drifting.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { createMessage, generateKey, readKey, readMessage, readPrivateKey, readSignature, verify } from 'openpgp';
import {
  COMPOSE_CAP,
  EXT_PICT,
  composeCost,
  composeSignedBytes,
  isValidThreadId,
  jcs,
  mentionsHint,
  onlySubdivisionFlag,
  refusedAt,
  type ComposeKind,
  type ComposeSuite,
} from './compose-rules';
import { buildSignedBytes, signWithEnvelope } from '../crypto/sign-envelope';
import { DOMAIN_LOOM_POST, DOMAIN_LOOM_TASK } from '../format/envelope';

const FIXTURE_PATH = join(__dirname, 'compose-vectors-v1.json');
const FIXTURE_SHA1 = '6aca9667ec9912dc83790ad8f72302f275b4e383';
const raw = readFileSync(FIXTURE_PATH);
const fx = JSON.parse(raw.toString('utf8'));

const cps = (hex: string[]): number[] => hex.map((h) => parseInt(h, 16));
const textOf = (hex: string[]): string => String.fromCodePoint(...cps(hex));
const kindOf = (domain: string): ComposeKind => (domain === DOMAIN_LOOM_POST ? 'post' : 'task');

test('the shared fixture is byte-identical to the one Athena published (sha1 pinned) and is the version this port targets', () => {
  assert.equal(createHash('sha1').update(raw).digest('hex'), FIXTURE_SHA1);
  assert.equal(fx.version, 1);
  assert.equal(fx.cap, COMPOSE_CAP);
  assert.equal(fx.cap, 2900);
  assert.equal(fx.domains.post, DOMAIN_LOOM_POST);
  assert.equal(fx.domains.task, DOMAIN_LOOM_TASK);
  assert.match(fx.WARNING, /THROWAWAY/);
  assert.doesNotMatch(raw.toString('utf8'), /PRIVATE KEY/, 'a fixture committed to the repo must carry no private key');
});

test('the pinned Extended_Pictographic table equals the fixture entry for entry (156 ranges, sorted, non-overlapping)', () => {
  const want = (fx.ext_pict_ranges as string[]).map((r) => r.split('-').map((h) => parseInt(h, 16)));
  assert.equal(want.length, 156);
  assert.deepEqual(EXT_PICT.map(([a, b]) => [a, b]), want);
  let prev = -1;
  for (const [a, b] of EXT_PICT) {
    assert.ok(a <= b && a > prev, `range ${a.toString(16)}-${b.toString(16)} out of order`);
    prev = b;
  }
});

test('text rules: every fixture vector (refused indices, receiver verdict, flag addendum, mention hint) is reproduced exactly', () => {
  assert.equal(fx.text.length, 32);
  for (const v of fx.text) {
    const text = textOf(v.input_cps);
    const refused = refusedAt(text);
    assert.deepEqual(refused, v.refused_indices, `${v.id}: refused indices`);
    assert.equal(refused.length > 0, v.receiver_rejects, `${v.id}: receiver verdict`);
    assert.equal(onlySubdivisionFlag(text), v.flag_addendum, `${v.id}: flag addendum`);
    assert.equal(mentionsHint(text), v.mention_hint, `${v.id}: mention hint`);
  }
});

test('text rules: the named classes the spec calls out, asserted by name (so a renamed vector cannot hide a dropped rule)', () => {
  const byId = (id: string) => fx.text.find((v: { id: string }) => v.id === id);
  for (const id of ['nul', 'del', 'c1-nel', 'ls', 'ps', 'bidi-rlo', 'bidi-isolate', 'zwsp', 'zwnj', 'bom', 'wj', 'tag-smuggle', 'vs1', 'vs17', 'zwj-letters', 'zwj-letter-vs16', 'lone-cr', 'tab']) {
    assert.ok(byId(id), `vector ${id} exists`);
    assert.ok(refusedAt(textOf(byId(id).input_cps)).length > 0, `${id} must be refused`);
  }
  // Allowed: an emoji ZWJ sequence, a skin-toned ZWJ sequence, VS15/VS16, and plain text with a newline.
  for (const id of ['plain', 'vs16-ok', 'vs15-ok', 'family', 'heart-on-fire', 'rainbow-flag', 'skin-tone-dev']) {
    assert.deepEqual(refusedAt(textOf(byId(id).input_cps)), [], `${id} must pass`);
  }
  assert.deepEqual(refusedAt('line one\nline two'), []);
});

test('text rules: a refusal is final: refusedAt is the only verdict and there is no normaliser in the app module', async () => {
  const mod = await import('./compose-rules');
  assert.equal('normalise' in mod, false, 'the portal is the single normaliser; the app never rewrites text');
  assert.ok(refusedAt('pe​ter').length > 0);
  assert.deepEqual(refusedAt('pe​ter'), [2]);
});

test('cost: every cap-boundary vector is reproduced; the recipe really builds the text the fixture hashed', () => {
  assert.equal(fx.cost.length, 12);
  for (const v of fx.cost) {
    const text = String.fromCodePoint(parseInt(v.recipe.repeat, 16)).repeat(v.recipe.times) + 'a'.repeat(v.recipe.then_ascii_a);
    assert.equal(createHash('sha256').update(text, 'utf8').digest('hex'), v.sha256_utf8, `${v.id}: recipe text hash`);
    assert.equal(composeCost(text), v.cost, `${v.id}: cost`);
    assert.equal(composeCost(text) <= COMPOSE_CAP, v.within_cap, `${v.id}: within cap`);
  }
});

test('thread id: [A-Za-z0-9:._/-]{1,64}; bidi, zero-width, empty, overlong and whitespace are all refused', () => {
  for (const ok of ['lane:portal', 'task:651', 'a', 'x'.repeat(64), 'a/b-c_d.e:f']) assert.equal(isValidThreadId(ok), true, ok);
  for (const bad of ['', 'x'.repeat(65), 'lane portal', 'lane\n', 'la​ne', 'la‮ne', 'lané', 'lane;drop']) assert.equal(isValidThreadId(bad), false, JSON.stringify(bad));
});

test('JCS: single-line, sorted ASCII keys, string values only; NOT the NFC-normalising canonicalize()', () => {
  assert.equal(jcs({ b: '2', a: '1' }), '{"a":"1","b":"2"}');
  // "shown = signed": a decomposed e-acute must survive byte for byte (canonicalize() would NFC it to U+00E9).
  const decomposed = 'é';
  assert.equal(jcs({ body: decomposed }), `{"body":"${decomposed}"}`);
  assert.notEqual(jcs({ body: decomposed }), jcs({ body: decomposed.normalize('NFC') }));
  assert.throws(() => jcs({ 'kéy': 'v' }), /ASCII/);
  assert.throws(() => jcs({ k: 1 as unknown as string }), /string values only/);
  // Control characters are escaped by JCS, so CR/LF can never appear raw in the signed bytes (Flint #831 V3).
  assert.doesNotMatch(jcs({ body: 'a\nb\r\nc' }), /[\r\n]/);
});

test('preimage: JCS and signed bytes match the fixture for the post, the hostile-JSON post and the task; the app uses the sign-envelope LP framing', () => {
  assert.equal(fx.preimage.length, 3);
  for (const v of fx.preimage) {
    assert.equal(jcs(v.object), v.jcs, `${v.id}: jcs`);
    const signed = composeSignedBytes(kindOf(v.domain), v.suite as ComposeSuite, v.object);
    assert.equal(signed, v.signed_bytes_utf8, `${v.id}: signed bytes`);
    assert.equal(signed, buildSignedBytes(v.domain, v.suite, v.jcs), `${v.id}: same framing as the app's existing signWithEnvelope`);
    assert.equal(createHash('sha256').update(signed, 'utf8').digest('hex'), v.sha256, `${v.id}: sha256`);
  }
  assert.throws(() => composeSignedBytes('post', 'ed25519+sha1' as ComposeSuite, { a: 'b' }), /unknown suite/);
});

async function verifyDetached(pub: Awaited<ReturnType<typeof readKey>>, sigB64: string, bytes: string): Promise<boolean> {
  const r = await verify({
    message: await createMessage({ text: bytes }),
    signature: await readSignature({ binarySignature: Buffer.from(sigB64, 'base64') }),
    verificationKeys: pub,
  });
  try {
    await r.signatures[0].verified;
    return true;
  } catch {
    return false;
  }
}

test('signatures: each stored 252-char packet verifies DETACHED against the bytes the app rebuilds; tamper, other loom domain, card domain and other suite all fail', async () => {
  const pub = await readKey({ armoredKey: fx.signature.test_public_key });
  assert.equal(pub.getFingerprint(), fx.signature.signing_key_fpr);
  assert.equal(fx.signature.vectors.length, fx.preimage.length);
  for (const s of fx.signature.vectors) {
    const p = fx.preimage.find((x: { id: string }) => x.id === s.id);
    assert.ok(p, `${s.id}: has a preimage`);
    const signed = composeSignedBytes(kindOf(p.domain), p.suite, p.object);
    assert.equal(s.stored_sig_b64.length, 252, `${s.id}: stored packet size`);
    assert.equal(s.sig_type, 1);
    assert.equal(s.hash_algo, 'sha512');
    assert.equal(s.issuer_fpr, fx.signature.signing_key_fpr);
    assert.equal(await verifyDetached(pub, s.stored_sig_b64, signed), true, `${s.id}: verifies`);
    // Recomputed here, not trusted from the fixture's recorded booleans.
    const swap = p.domain === DOMAIN_LOOM_POST ? DOMAIN_LOOM_TASK : DOMAIN_LOOM_POST;
    const neg = {
      body_tampered: signed.replace(/.$/, signed.endsWith('}') ? ' }' : '}'),
      other_loom_domain: buildSignedBytes(swap, p.suite, p.jcs),
      identity_card_domain: buildSignedBytes('svrnty:identity-card:v1', p.suite, p.jcs),
      other_suite: buildSignedBytes(p.domain, 'ed25519+ml-dsa-87', p.jcs),
    };
    for (const [name, bytes] of Object.entries(neg)) {
      assert.equal(await verifyDetached(pub, s.stored_sig_b64, bytes), false, `${s.id}: ${name} must NOT verify`);
      assert.equal(s.negative[name], false, `${s.id}: fixture records ${name} as false`);
    }
  }
});

function allSourceTags(): Set<string> {
  const tags = new Set<string>();
  const root = join(__dirname, '..', '..');
  const walk = (dir: string) => {
    for (const name of readdirSync(dir)) {
      const p = join(dir, name);
      if (statSync(p).isDirectory()) {
        if (name !== 'node_modules') walk(p);
      } else if (/\.tsx?$/.test(name) && !/\.test\.tsx?$/.test(name)) {
        for (const m of readFileSync(p, 'utf8').matchAll(/'(svrnty:[a-z0-9-]+:v\d+)'/g)) tags.add(m[1]);
      }
    }
  };
  walk(root);
  return tags;
}

test('domain separation (both directions, real signatures): a loom post/task signature never verifies as any other svrnty domain, and none of them verifies as a post/task', async () => {
  const others = [...allSourceTags()].filter((t) => t !== DOMAIN_LOOM_POST && t !== DOMAIN_LOOM_TASK);
  assert.ok(others.length >= 10, `scanned ${others.length} other domain tags`);
  for (const must of ['svrnty:identity-card:v1', 'svrnty:trust-signal:v1', 'svrnty:note:v0', 'svrnty:rotation:v1', 'svrnty:contact-update:v1']) {
    assert.ok(others.includes(must), `the scan sees ${must}`);
  }
  const passphrase = 'compose-test';
  const { privateKey, publicKey } = await generateKey({ type: 'ecc', curve: 'curve25519Legacy', userIDs: [{ name: 't' }], passphrase, format: 'armored' });
  const pub = await readKey({ armoredKey: publicKey });
  await readPrivateKey({ armoredKey: privateKey }); // parses
  const input = jcs({ body: 'same canonical input everywhere' });

  const detachedSig = async (tag: string): Promise<string> => {
    const att = await signWithEnvelope(tag, input, privateKey, passphrase);
    const res = await verify({ message: await readMessage({ armoredMessage: att.classical }), verificationKeys: pub, expectSigned: true });
    const sig = await res.signatures[0].signature;
    return Buffer.from(sig.write()).toString('base64');
  };

  const all = [DOMAIN_LOOM_POST, DOMAIN_LOOM_TASK, ...others];
  for (const signer of [DOMAIN_LOOM_POST, DOMAIN_LOOM_TASK, ...others]) {
    const sigB64 = await detachedSig(signer);
    for (const verifier of all) {
      const ok = await verifyDetached(pub, sigB64, buildSignedBytes(verifier, 'ed25519', input));
      assert.equal(ok, signer === verifier, `signed as ${signer}, checked as ${verifier}: expected ${signer === verifier}`);
    }
  }
});

test('the two new tags are distinct from every other tag in the source and appear only where intended', () => {
  const others = [...allSourceTags()].filter((t) => t !== DOMAIN_LOOM_POST && t !== DOMAIN_LOOM_TASK);
  assert.notEqual(DOMAIN_LOOM_POST, DOMAIN_LOOM_TASK);
  assert.equal(others.includes(DOMAIN_LOOM_POST), false);
  assert.equal(others.includes(DOMAIN_LOOM_TASK), false);
  assert.equal(DOMAIN_LOOM_POST, 'svrnty:loom-post:v1');
  assert.equal(DOMAIN_LOOM_TASK, 'svrnty:loom-task:v1');
});
